)
```

## 2. Creating the Repository for Categories

```kotlin:app/src/main/java/tungp/android/bazarbooks/data/repository/CategoryRepository.kt
package tungp.android.bazarbooks.data.repository

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.flowOn
import tungp.android.bazarbooks.data.model.Category
import retrofit2.http.GET
import javax.inject.Inject

interface CategoryApiService {
 @GET("categories")
 suspend fun getCategories(): List<Category>
}

class CategoryRepository @Inject constructor(
 private val categoryApiService: CategoryApiService
) {
 fun getAllCategories(): Flow<List<Category>> = flow {
 try {
 val categories = categoryApiService.getCategories()
 emit(categories)
 } catch (e: Exception) {
 // In a real app, you'd handle the error properly
 emit(emptyList())
 }
 }.flowOn(Dispatchers.IO)
}
```

## 3. Create a ViewModel for the CategoryScreen

```kotlin:app/src/main/java/tungp/android/bazarbooks/screens/category/CategoryViewModel.kt
package tungp.android.bazarbooks.screens.category

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.launch
import tungp.android.bazarbooks.data.model.Category
import tungp.android.bazarbooks.data.repository.CategoryRepository
import javax.inject.Inject

@HiltViewModel
class CategoryViewModel @Inject constructor(
 private val categoryRepository: CategoryRepository
) : ViewModel() {

 private val _categoriesState = MutableStateFlow<CategoriesState>(CategoriesState.Loading)
 val categoriesState: StateFlow<CategoriesState> = _categoriesState

 init {
 loadCategories()
 }

 private fun loadCategories() {
 viewModelScope.launch {
 categoryRepository.getAllCategories()
 .catch { e ->
 _categoriesState.value = CategoriesState.Error(e.message ?: "Unknown error")
 }
 .collect { categories ->
 _categoriesState.value = CategoriesState.Success(categories)
 }
 }
 }

 sealed class CategoriesState {
 object Loading : CategoriesState()
 data class Success(val categories: List<Category>) : CategoriesState()
 data class Error(val message: String) : CategoriesState()
 }
}
```

## 4. Updating the CategoryScreen to Display Categories

Now let's update your current CategoryScreen to use the ViewModel and display the categories:

```kotlin:app/src/main/java/tungp/android/bazarbooks/screens/category/CategoryScreen.kt
package tungp.android.bazarbooks.screens.category

import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.navigation.NavController
import androidx.navigation.compose.rememberNavController
import tungp.android.bazarbooks.data.model.Category
import tungp.android.bazarbooks.navigation.CategoryRouteScreen

@Composable
fun CategoryScreen(
 navController: NavController,
 viewModel: CategoryViewModel = hiltViewModel()
) {
 val categoriesState by viewModel.categoriesState.collectAsState()

 Column(
 modifier = Modifier
 .fillMaxSize()
 .background(Color.White)
 ) {
 Text(
 text = "Book Categories",
 fontSize = 24.sp,
 fontWeight = FontWeight.Bold,
 modifier = Modifier.padding(16.dp)
 )

 when (categoriesState) {
 is CategoryViewModel.CategoriesState.Loading -> {
 Box(modifier = Modifier.fillMaxSize()) {
 CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
 }
 }
 is CategoryViewModel.CategoriesState.Error -> {
 val errorState = categoriesState as CategoryViewModel.CategoriesState.Error
 Box(modifier = Modifier.fillMaxSize()) {
 Column(
 modifier = Modifier.align(Alignment.Center),
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text("Error: ${errorState.message}")
 Button(onClick = { /* Retry logic here */ }) {
 Text("Retry")
 }
 }
 }
 }
 is CategoryViewModel.CategoriesState.Success -> {
 val categories = (categoriesState as CategoryViewModel.CategoriesState.Success).categories
 CategoryList(categories = categories) { categoryId ->
 navController.navigate("${CategoryRouteScreen.CategoryDetail.route}/$categoryId")
 }
 }
 }
 }
}

@Composable
fun CategoryList(
 categories: List<Category>,
 onCategoryClick: (String) -> Unit
) {
 LazyColumn(
 modifier = Modifier.fillMaxSize(),
 contentPadding = PaddingValues(16.dp),
 verticalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 items(categories) { category ->
 CategoryItem(category = category, onClick = { onCategoryClick(category.id) })
 }
 }
}

@Composable
fun CategoryItem(
 category: Category,
 onClick: () -> Unit
) {
 Card(
 modifier = Modifier
 .fillMaxWidth()
 .clickable(onClick = onClick),
 elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
 ) {
 Column(
 modifier = Modifier
 .fillMaxWidth()
 .padding(16.dp)
 ) {
 Text(
 text = category.name,
 fontSize = 18.sp,
 fontWeight = FontWeight.Bold
 )
 category.description?.let {
 Spacer(modifier = Modifier.height(4.dp))
 Text(
 text = it,
 fontSize = 14.sp,
 maxLines = 2
 )
 }
 }
 }
}

@Preview
@Composable
private fun CategoryScreenPreview() {
 val previewCategories = listOf(
 Category("1", "Fiction", "Books of fiction genre"),
 Category("2", "Non-Fiction", "Educational books"),
 Category("3", "Science", "Science and technology books"),
 )

 Column(modifier = Modifier.fillMaxSize()) {
 Text(
 text = "Book Categories",
 fontSize = 24.sp,
 fontWeight = FontWeight.Bold,
 modifier = Modifier.padding(16.dp)
 )
 CategoryList(categories = previewCategories) { }
 }
}
```

## 5. Add DI Module for API Service and Repository

```kotlin:app/src/main/java/tungp/android/bazarbooks/di/NetworkModule.kt
package tungp.android.bazarbooks.di

import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import tungp.android.bazarbooks.data.repository.CategoryApiService
import tungp.android.bazarbooks.data.repository.CategoryRepository
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
object NetworkModule {

 @Provides
 @Singleton
 fun provideRetrofit(): Retrofit {
 return Retrofit.Builder()
 .baseUrl("https://your-api-base-url.com/api/") // Replace with your actual API base URL
 .addConverterFactory(GsonConverterFactory.create())
 .build()
 }

 @Provides
 @Singleton
 fun provideCategoryApiService(retrofit: Retrofit): CategoryApiService {
 return retrofit.create(CategoryApiService::class.java)
 }

 @Provides
 @Singleton
 fun provideCategoryRepository(apiService: CategoryApiService): CategoryRepository {
 return CategoryRepository(apiService)
 }
}
```

