## 2. Let's create a horizontal categories component

```kotlin:app/src/main/java/tungp/android/bazarbooks/presentation/components/HorizontalCategoriesComponent.kt
package tungp.android.bazarbooks.presentation.components

import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyRow
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import tungp.android.bazarbooks.domain.model.VendorCategory

@Composable
fun HorizontalCategoriesComponent(
 categories: List<VendorCategory>,
 onCategorySelected: (String) -> Unit,
 modifier: Modifier = Modifier
) {
 LazyRow(
 modifier = modifier.fillMaxWidth(),
 contentPadding = PaddingValues(horizontal = 16.dp),
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 items(categories) { category ->
 CategoryChip(
 category = category,
 onCategorySelected = { onCategorySelected(category.id) }
 )
 }
 }
}

@Composable
fun CategoryChip(
 category: VendorCategory,
 onCategorySelected: () -> Unit
) {
 Box(
 modifier = Modifier
 .clip(RoundedCornerShape(16.dp))
 .background(
 if (category.isSelected) MaterialTheme.colorScheme.primary
 else MaterialTheme.colorScheme.surfaceVariant
 )
 .clickable { onCategorySelected() }
 .padding(horizontal = 16.dp, vertical = 8.dp),
 contentAlignment = Alignment.Center
 ) {
 Text(
 text = category.name,
 style = MaterialTheme.typography.bodyMedium,
 fontWeight = if (category.isSelected) FontWeight.Bold else FontWeight.Normal,
 color = if (category.isSelected) Color.White else MaterialTheme.colorScheme.onSurfaceVariant
 )
 }
}
