## 3. Let's create a ViewModel to handle vendor categories and the filtering logic

```kotlin:app/src/main/java/tungp/android/bazarbooks/presentation/viewmodels/VendorViewModel.kt
package tungp.android.bazarbooks.presentation.viewmodels

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import tungp.android.bazarbooks.domain.model.Vendor
import tungp.android.bazarbooks.domain.model.VendorCategory
import tungp.android.bazarbooks.domain.repository.VendorRepository
import javax.inject.Inject

@HiltViewModel
class VendorViewModel @Inject constructor(
 private val vendorRepository: VendorRepository
) : ViewModel() {

 private val _uiState = MutableStateFlow(VendorUiState())
 val uiState: StateFlow<VendorUiState> = _uiState.asStateFlow()

 init {
 loadVendors()
 setupCategories()
 }

 private fun loadVendors() {
 viewModelScope.launch {
 try {
 val vendors = vendorRepository.getVendors()
 _uiState.update { currentState ->
 currentState.copy(
 allVendors = vendors,
 filteredVendors = vendors,
 isLoading = false
 )
 }
 } catch (e: Exception) {
 _uiState.update { currentState ->
 currentState.copy(
 error = e.message ?: "Failed to load vendors",
 isLoading = false
 )
 }
 }
 }
 }

 private fun setupCategories() {
 val predefinedCategories = listOf(
 VendorCategory(id = "all", name = "All", isSelected = true),
 VendorCategory(id = "special", name = "Special for you"),
 VendorCategory(id = "poems", name = "Poems"),
 VendorCategory(id = "stationary", name = "Stationary"),
 VendorCategory(id = "books", name = "Books")
 )

 _uiState.update { currentState ->
 currentState.copy(categories = predefinedCategories)
 }
 }

 fun selectCategory(categoryId: String) {
 // Update selected category
 val updatedCategories = _uiState.value.categories.map { category ->
 category.copy(isSelected = category.id == categoryId)
 }

 // Filter vendors based on selected category
 val filteredVendors = if (categoryId == "all") {
 _uiState.value.allVendors
 } else {
 // In a real app, you'd have a type field in the Vendor class
 // This is a placeholder implementation
 _uiState.value.allVendors.filter { vendor ->
 when (categoryId) {
 "special" -> vendor.title.contains("special", ignoreCase = true)
 "poems" -> vendor.title.contains("poem", ignoreCase = true)
 "stationary" -> vendor.title.contains("stationary", ignoreCase = true)
 "books" -> vendor.title.contains("book", ignoreCase = true)
 else -> true
 }
 }
 }

 _uiState.update { currentState ->
 currentState.copy(
 categories = updatedCategories,
 filteredVendors = filteredVendors
 )
 }
 }

 data class VendorUiState(
 val allVendors: List<Vendor> = emptyList(),
 val filteredVendors: List<Vendor> = emptyList(),
 val categories: List<VendorCategory> = emptyList(),
 val isLoading: Boolean = true,
 val error: String? = null
 )
}
```

