Let's implement a reusable rating component that can display star ratings and optionally allow users to set ratings.

```kotlin:app/src/main/java/tungp/android/bazarbooks/components/RatingComponent.kt
package tungp.android.bazarbooks.components

import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.size
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Star
import androidx.compose.material.icons.filled.StarBorder
import androidx.compose.material.icons.filled.StarHalf
import androidx.compose.material3.Icon
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import kotlin.math.ceil
import kotlin.math.floor

/**
 * A customizable rating component that displays star ratings
 *
 * @param rating The current rating value (0.0 to 5.0)
 * @param maxRating The maximum rating possible (default is 5)
 * @param starSize The size of each star icon
 * @param starColor The color of filled stars
 * @param starSpacing The spacing between stars
 * @param isIndicatorOnly If true, rating is display only (not interactive)
 * @param onRatingChanged Callback when rating changes (only used when isIndicatorOnly is false)
 * @param modifier Modifier to be applied to the component
 */
@Composable
fun RatingComponent(
 rating: Float,
 maxRating: Int = 5,
 starSize: Dp = 24.dp,
 starColor: Color = Color(0xFFFFC107), // Amber color for stars
 unfillColor: Color = Color(0xFFBDBDBD), // Grey for unfilled stars
 starSpacing: Dp = 4.dp,
 isIndicatorOnly: Boolean = true,
 showHalfStars: Boolean = true,
 onRatingChanged: (Float) -> Unit = {},
 modifier: Modifier = Modifier
) {
 // Ensure rating is within bounds
 val boundedRating = rating.coerceIn(0f, maxRating.toFloat())

 Row(
 modifier = modifier,
 horizontalArrangement = Arrangement.spacedBy(starSpacing)
 ) {
 for (i in 1..maxRating) {
 val starFill = boundedRating - (i - 1)

 if (isIndicatorOnly) {
 // Display only mode - shows the current rating
 when {
 starFill >= 1f -> {
 // Full star
 Icon(
 imageVector = Icons.Default.Star,
 contentDescription = null,
 tint = starColor,
 modifier = Modifier.size(starSize)
 )
 }
 starFill > 0f && showHalfStars -> {
 // Half star
 Icon(
 imageVector = Icons.Default.StarHalf,
 contentDescription = null,
 tint = starColor,
 modifier = Modifier.size(starSize)
 )
 }
 else -> {
 // Empty star
 Icon(
 imageVector = Icons.Default.StarBorder,
 contentDescription = null,
 tint = unfillColor,
 modifier = Modifier.size(starSize)
 )
 }
 }
 } else {
 // Interactive mode - allows setting the rating
 Icon(
 imageVector = if (i <= boundedRating) Icons.Default.Star else Icons.Default.StarBorder,
 contentDescription = "Rate $i out of $maxRating",
 tint = if (i <= boundedRating) starColor else unfillColor,
 modifier = Modifier
 .size(starSize)
 .clickable { onRatingChanged(i.toFloat()) }
 .padding(2.dp) // Add some padding to make clicking easier
 )
 }
 }
 }
}

/**
 * A more precise rating component that properly handles partial stars
 */
@Composable
fun PreciseRatingBar(
 rating: Float,
 maxRating: Int = 5,
 starSize: Dp = 24.dp,
 starColor: Color = Color(0xFFFFC107),
 unfillColor: Color = Color(0xFFBDBDBD),
 starSpacing: Dp = 4.dp,
 modifier: Modifier = Modifier
) {
 Row(
 modifier = modifier,
 horizontalArrangement = Arrangement.spacedBy(starSpacing)
 ) {
 for (i in 1..maxRating) {
 val starFill = rating - (i - 1)
 when {
 starFill >= 1f -> {
 // Full star
 Icon(
 imageVector = Icons.Default.Star,
 contentDescription = null,
 tint = starColor,
 modifier = Modifier.size(starSize)
 )
 }
 starFill > 0f -> {
 // Partial star - we use half star for simplicity
 // In a more advanced implementation, you could draw a partially filled star
 Icon(
 imageVector = Icons.Default.StarHalf,
 contentDescription = null,
 tint = starColor,
 modifier = Modifier.size(starSize)
 )
 }
 else -> {
 // Empty star
 Icon(
 imageVector = Icons.Default.StarBorder,
 contentDescription = null,
 tint = unfillColor,
 modifier = Modifier.size(starSize)
 )
 }
 }
 }
 }
}

@Preview(showBackground = true)
@Composable
fun RatingPreview() {
 Row {
 // Static rating display
 RatingComponent(
 rating = 3.5f,
 starSize = 20.dp,
 modifier = Modifier.padding(8.dp)
 )
 }
}

@Preview(showBackground = true)
@Composable
fun InteractiveRatingPreview() {
 Row {
 // Interactive rating component
 RatingComponent(
 rating = 3f,
 isIndicatorOnly = false,
 starSize = 32.dp,
 modifier = Modifier.padding(8.dp),
 onRatingChanged = { /* Handle rating change */ }
 )
 }
}

@Preview(showBackground = true)
@Composable
fun PreciseRatingPreview() {
 Row {
 // Precise rating bar that shows half stars
 PreciseRatingBar(
 rating = 3.7f, 
 starSize = 24.dp,
 modifier = Modifier.padding(8.dp)
 )
 }
}
```

